mapper.select:
SELECT a.id AS swapId, a.apply_user_id AS applyUserId, u1.real_name AS applyUserName, a.apply_seat_id AS applySeatId, s1.seat_no AS applySeatNo, a.target_user_id AS targetUserId, u2.real_name AS targetUserName, a.target_seat_id AS targetSeatId, s2.seat_no AS targetSeatNo, a.reason AS reason, a.status AS status, a.handle_time AS handleTime, a.handle_remark AS handleRemark, u3.real_name AS auditUserName, a.audit_time AS auditTime, a.audit_remark AS auditRemark, a.create_time AS createTime FROM seat_swap a LEFT JOIN sys_user u1 ON a.apply_user_id = u1.id AND u1.deleted = 0 LEFT JOIN sys_user u2 ON a.target_user_id = u2.id AND u2.deleted = 0 LEFT JOIN sys_user u3 ON a.audit_user_id = u3.id AND u3.deleted = 0 LEFT JOIN seat_info s1 ON a.apply_seat_id = s1.id AND s1.deleted = 0 LEFT JOIN seat_info s2 ON a.target_seat_id = s2.id AND s2.deleted = 0 WHERE a.deleted = 0
AND a.apply_user_id = #{currentUserId}
AND a.target_user_id = #{currentUserId}
AND (a.apply_user_id = #{currentUserId} OR a.target_user_id = #{currentUserId})
AND a.status = #{query.status}
ORDER BY a.create_time DESC

SELECT s.id AS swapId, s.apply_user_id AS applyUserId, u1.real_name AS applyUserName, u1.grade AS applyUserGrade, s.apply_seat_id AS applySeatId, si1.seat_no AS applySeatNo, s.target_user_id AS targetUserId, u2.real_name AS targetUserName, u2.grade AS targetUserGrade, s.target_seat_id AS targetSeatId, si2.seat_no AS targetSeatNo, s.reason AS reason, s.status AS status, s.handle_time AS handleTime, s.handle_remark AS handleRemark, s.audit_user_id AS auditUserId, u3.real_name AS auditUserName, s.audit_time AS auditTime, s.audit_remark AS auditRemark, s.create_time AS createTime FROM seat_swap s LEFT JOIN sys_user u1 ON s.apply_user_id = u1.id AND u1.deleted = 0 LEFT JOIN sys_user u2 ON s.target_user_id = u2.id AND u2.deleted = 0 LEFT JOIN sys_user u3 ON s.audit_user_id = u3.id AND u3.deleted = 0 LEFT JOIN seat_info si1 ON s.apply_seat_id = si1.id AND si1.deleted = 0 LEFT JOIN seat_info si2 ON s.target_seat_id = si2.id AND si2.deleted = 0 WHERE s.deleted = 0
AND s.status = #{query.status}
AND (s.apply_user_id = #{query.userId} OR s.target_user_id = #{query.userId})
AND (u1.real_name LIKE CONCAT('%', #{query.keyword}, '%') OR u2.real_name LIKE CONCAT('%', #{query.keyword}, '%') OR si1.seat_no LIKE CONCAT('%', #{query.keyword}, '%') OR si2.seat_no LIKE CONCAT('%', #{query.keyword}, '%'))
AND s.create_time >= #{query.beginTime}
AND s.create_time <= #{query.endTime}
ORDER BY s.create_time DESC
